securityRules.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isValidSessionWrite() {
      let data = request.resource.data;
      return data.keys().hasOnly(['id', 'config', 'players', 'rounds', 'upcomingMatches', 'openPlay', 'ownerUid', 'organizerToken', 'updatedAt', 'createdAt', 'deviceOrigin']) && data.id is string && data.id.size() > 0 && data.id.size() <= 64 && data.organizerToken is string && data.organizerToken.size() > 0 && data.organizerToken.size() <= 128 && (!('updatedAt' in data) || data.updatedAt is number) && (!('createdAt' in data) || data.createdAt is number) && (!('config' in data) || data.config is map) && (!('players' in data) || data.players is list) && (!('rounds' in data) || data.rounds is list) && (!('upcomingMatches' in data) || data.upcomingMatches is list) && (!('openPlay' in data) || data.openPlay is map) && (!('ownerUid' in data) || (data.ownerUid is string && data.ownerUid.size() <= 128)) && (!('deviceOrigin' in data) || (data.deviceOrigin is string && data.deviceOrigin.size() <= 256));
    }
    match /sessions/{sessionId} {
      allow read: if true;
      allow create: if isValidSessionWrite() && request.resource.data.organizerToken is string && request.resource.data.organizerToken.size() > 0;
      allow update: if isValidSessionWrite() && resource.data.organizerToken != null && request.resource.data.organizerToken == resource.data.organizerToken;
      allow delete: if request.auth != null && resource.data.ownerUid == request.auth.uid;
    }
    match /users/{userId} {
      allow read: if request.auth != null;
      allow write: if request.auth != null && request.auth.uid == userId;
    }
    match /playerProfiles/{profileId} {
      allow read: if request.auth != null;
      allow write: if request.resource.data.name is string && request.resource.data.name.size() > 0 && request.resource.data.name.size() <= 64;
    }
  }
}
